          authMethod = null;
        }
      } catch (IllegalArgumentException iae) {
        authMethod = null;
      }
      if (authMethod != null &&
          // sasl server for tokens may already be instantiated
          (saslServer == null || authMethod != AuthMethod.TOKEN)) {
        saslServer = createSaslServer(authMethod);
      }
      return authMethod;
    }

